B.afm=s(["iPhone\uc758 iCloud \ubc31\uc5c5\uc774\ub098 Android\uc758 \uc790\ub3d9 \ubc31\uc5c5\uc744 \ucf1c \ub450\uba74, \uc6b4\uc601\uccb4\uc81c\uac00 \uc571 \ub370\uc774\ud130\ub97c \ubc31\uc5c5\uc5d0 \ud568\uaed8 \ub2f4\uc744 \uc218 \uc788\uc5b4\uc694.","\uc774 \ubc31\uc5c5\uc740 \uc560\ud50c\uc774\ub098 \uad6c\uae00\uc774 \uc5ec\ub7ec\ubd84\uc758 \uacc4\uc815\uc5d0\uc11c \uad00\ub9ac\ud558\ub294 \uac83\uc774\uace0, \uc6b0\ub9ac\uac00 \uadf8 \ub0b4\uc6a9\uc744 \ubcf4\uac70\ub098 \uac00\uc838\uc62c \uc218\ub294 \uc5c6\uc5b4\uc694.","\ubc31\uc5c5\uc5d0 \ub2f4\uae30\uc9c0 \uc54a\uac8c \ud558\ub824\uba74 \uae30\uae30 \uc124\uc815\uc5d0\uc11c \uc774 \uc571\uc758 \ubc31\uc5c5\uc744 \uaebc \uc8fc\uc138\uc694."],t.s)
B.aE0=new A.l8("4. \uae30\uae30 \uc790\ub3d9 \ubc31\uc5c5",B.afm)
B.akV=s(["\uc571\uc740 \uc2dc\ud5d8 \uc77c\uc815\uc744 \ucd5c\uc2e0\uc73c\ub85c \uc720\uc9c0\ud558\ub824\uace0 \uc815\ud574\uc9c4 \uc8fc\uc18c\uc758 \uc791\uc740 \ud30c\uc77c \ud558\ub098\ub97c \ub0b4\ub824\ubc1b\uc544\uc694. \uc6f9\uc5d0\uc11c\ub294 \uc0c8 \ubc84\uc804\uc774 \ub098\uc654\ub294\uc9c0 \ud655\uc778\ud558\ub294 \ud30c\uc77c\ub3c4 \ud568\uaed8 \ud655\uc778\ud574\uc694.",'\uc774\ub54c \ubcf4\ub0b4\ub294 \uac74 "\uadf8 \ud30c\uc77c\uc744 \uc8fc\uc138\uc694"\ub77c\ub294 \uc694\uccad\ubfd0\uc774\uc5d0\uc694. \ud559\uc2b5 \uae30\ub85d\uc774\ub098 \uae30\uae30 \uc548\uc758 \uc815\ubcf4\ub294 \ud568\uaed8 \ubcf4\ub0b4\uc9c0 \uc54a\uc544\uc694.',"\ub2e4\ub9cc \uc778\ud130\ub137 \uc694\uccad\uc740 \uadf8 \ud30c\uc77c\uc744 \ubcf4\uad00\ud558\ub294 \ud638\uc2a4\ud305 \ud68c\uc0ac\uc758 \uc11c\ubc84\ub97c \uac70\uce58\uae30 \ub54c\ubb38\uc5d0, \uc811\uc18d \uc2dc\uac01\uacfc IP \uc8fc\uc18c \uac19\uc740 \uc811\uc18d \uae30\ub85d\uc774 \uadf8 \ud68c\uc0ac \ucabd\uc5d0 \uc7a0\uc2dc \ub0a8\uc744 \uc218 \uc788\uc5b4\uc694. \uc774 \uae30\ub85d\uc740 \uc6b0\ub9ac\uac00 \ub9cc\ub4e4\uc9c0\ub3c4 \ubcf4\uad00\ud558\uc9c0\ub3c4 \uc54a\uc544\uc694."],t.s)
B.aDW=new A.l8("5. \uc778\ud130\ub137\uc744 \uc4f0\ub294 \uc21c\uac04",B.akV)
B.al9=s(['"\uc790\ub791\ud558\uae30"\uc5d0\uc11c \ub9cc\ub4e0 \uae30\ub85d\uc99d \uc774\ubbf8\uc9c0\ub098 \ud559\uc2b5 \uae30\ub85d \ud30c\uc77c\uc740 \uc5ec\ub7ec\ubd84\uc774 \uc9c1\uc811 \ub0b4\ubcf4\ub0bc \ub54c\ub9cc \uae30\uae30 \ubc16\uc73c\ub85c \ub098\uac00\uc694.',"\ub0b4\ubcf4\ub0b4\uae30\ub97c \ub204\ub974\uba74 \uae30\uae30\uc758 \uacf5\uc720 \ucc3d\uc774 \uc5f4\ub9ac\uace0, \uac70\uae30\uc11c \uace0\ub978 \uc571(\uba54\uc2dc\uc9c0, \uc0ac\uc9c4\ucca9 \ub4f1)\uc73c\ub85c\ub9cc \uc804\ub2ec\ub3fc\uc694. \uc6b0\ub9ac \uc11c\ubc84\ub85c\ub294 \uc544\ubb34\uac83\ub3c4 \uac00\uc9c0 \uc54a\uc544\uc694.","\uae30\ub85d\uc99d \uc774\ubbf8\uc9c0\uc5d0\ub294 \uc774\ub984\uc774\ub098 \uc5f0\ub77d\ucc98\uac00 \ub4e4\uc5b4\uac00\uc9c0 \uc54a\uc544\uc694."],t.s)
B.aDZ=new A.l8("6. \uae30\ub85d\uc744 \ub0b4\ubcf4\ub0bc \ub54c",B.al9)
B.amY=s(["\ud559\uc2b5 \uae30\ub85d\uc740 \uc5ec\ub7ec\ubd84\uc774 \uc9c0\uc6b8 \ub54c\uae4c\uc9c0 \uae30\uae30\uc5d0 \ub0a8\uc544\uc694. \uc6b0\ub9ac\uac00 \ub530\ub85c \uc815\ud55c \ubcf4\uad00 \uae30\uac04\uc740 \uc5c6\uc5b4\uc694.","\uae30\ub85d\uc744 \uc9c0\uc6b0\ub824\uba74 \ub450 \uac00\uc9c0 \ubc29\ubc95\uc774 \uc788\uc5b4\uc694.",'\xb7 \uc124\uc815 \ud654\uba74\uc758 "\ud559\uc2b5 \uae30\ub85d"\uc5d0\uc11c \uae30\ub85d \ucd08\uae30\ud654\ub97c \ub204\ub974\uba74 \ud559\uc2b5 \uae30\ub85d\uc774 \uc9c0\uc6cc\uc838\uc694.',"\xb7 \uc571\uc744 \uc0ad\uc81c\ud558\uba74 \uc571\uc774 \ub9cc\ub4e0 \ub370\uc774\ud130\uac00 \uae30\uae30\uc5d0\uc11c \ud568\uaed8 \uc0ac\ub77c\uc838\uc694.","\uae30\uae30 \uc790\ub3d9 \ubc31\uc5c5\uc5d0 \uc774\ubbf8 \ub2f4\uae34 \ub0b4\uc6a9\uc740 \uae30\uae30 \uc124\uc815\uc758 \ubc31\uc5c5 \uad00\ub9ac\uc5d0\uc11c \uc9c0\uc6cc \uc8fc\uc138\uc694."],t.s)
B.aDV=new A.l8("7. \ubcf4\uad00 \uae30\uac04\uacfc \uc9c0\uc6b0\ub294 \ubc29\ubc95",B.amY)
B.abs=s(["\uc774 \uc571\uc740 \ucd08\ub4f1\ud559\uc0dd\uacfc \uc911\ud559\uc0dd\uc774 \ud55c\uc790\ub97c \uacf5\ubd80\ud558\ub3c4\ub85d \ub9cc\ub4e4\uc5c8\uc5b4\uc694. \uac1c\uc778\uc815\ubcf4\ub97c \ubaa8\uc73c\uc9c0 \uc54a\uc73c\ub2c8 \uac00\uc785\ud560 \ub54c \ubcf4\ud638\uc790 \ub3d9\uc758\ub97c \ubc1b\ub294 \uc808\ucc28\ub3c4 \uc5c6\uc5b4\uc694. \uc5f0\uad6c \ucc38\uc5ec\ub294 \uc608\uc678\uc608\uc694. \ubaa8\uc9d1\ud560 \ub54c \ubcf4\ud638\uc790 \ub3d9\uc758\ub97c \uba3c\uc800 \ubc1b\uc544\uc694(9\uc808).","\ubcf4\ud638\uc790\uaed8\uc11c\ub294 \uc790\ub140\uc758 \uae30\uae30\uc5d0\uc11c \uc571 \uc124\uc815\uacfc \ud559\uc2b5 \uae30\ub85d\uc744 \uc9c1\uc811 \ud655\uc778\ud558\uace0 \uc9c0\uc6b8 \uc218 \uc788\uc5b4\uc694.","\ub098\uc911\uc5d0 \uacc4\uc815\uc774\ub098 \ub3d9\uae30\ud654 \uae30\ub2a5\uc774 \uc0dd\uaca8\uc11c \uac1c\uc778\uc815\ubcf4\ub97c \ub2e4\ub8e8\uac8c \ub418\uba74, \uadf8\ub54c\ub294 \ubc95\uc5d0 \ub530\ub77c \ubcf4\ud638\uc790 \ub3d9\uc758\ub97c \uba3c\uc800 \ubc1b\uace0 \uc774 \ubc29\uce68\ub3c4 \ubbf8\ub9ac \uace0\uccd0\uc11c \uc54c\ub824 \ub4dc\ub9b4\uac8c\uc694."],t.s)
B.aE3=new A.l8("8. \ub9cc 14\uc138 \ubbf8\ub9cc \uc5b4\ub9b0\uc774\uc640 \ubcf4\ud638\uc790\uc5d0\uac8c",B.abs)
B.ajp=s(["\uc571\uc744 \ub354 \uc88b\uac8c \ub9cc\ub4e4\ub824\uace0, \uc6b4\uc601\uc790\uac00 \ubbf8\ub9ac \ubaa8\uc9d1\ud55c \ucc38\uc5ec\uc790\uc5d0\uac8c\uc11c\ub9cc \ud559\uc2b5 \ud69f\uc218\ub97c \ubaa8\uc740 \ud30c\uc77c\uc744 \ubc1b\uc544\uc694. \ucc38\uc5ec\ub294 \uc120\ud0dd\uc774\uace0, \ucc38\uc5ec\ud558\uc9c0 \uc54a\uc544\ub3c4 \uc571\uc758 \ubaa8\ub4e0 \uae30\ub2a5\uc744 \uadf8\ub300\ub85c \uc4f8 \uc218 \uc788\uc5b4\uc694.",'\ub9cc 14\uc138 \ubbf8\ub9cc \ucc38\uc5ec\uc790\ub294 \ubaa8\uc9d1\ud560 \ub54c \ubcf4\ud638\uc790(\ubc95\uc815\ub300\ub9ac\uc778)\uc5d0\uac8c \uba3c\uc800 \ub3d9\uc758\ub97c \ubc1b\uc544\uc694. \uc571\ub3c4 \ud30c\uc77c\uc744 \ubcf4\ub0b4\uae30 \uc804\uc5d0 "\ubcf4\ud638\uc790 \ub3d9\uc758\ub97c \ubc1b\uc740 \ucc38\uc5ec\uc790\ub9cc" \ubcf4\ub0b4 \ub2ec\ub77c\uace0 \ud55c \ubc88 \ub354 \uc54c\ub824\uc694.',"\ud30c\uc77c\uc5d0 \ub2f4\uae30\ub294 \uac83\uc740 \uc6b4\uc601\uc790\uac00 \ub098\ub220 \uc900 \ucc38\uc5ec \ucf54\ub4dc, \ubaa9\ud45c \uae09\uc218, \uccab \ud559\uc2b5\uc77c\ubd80\ud130 \uba70\uce60\uc9f8\uc778\uc9c0\ub97c \uc13c \ub0a0\uc9dc \ubc88\ud638\uc640 \uadf8\ub0a0\uc758 \ud559\uc2b5 \uc2dc\uc791\xb7\uc644\ub8cc \uac19\uc740 \ub3d9\uc791 \ud69f\uc218, \uae09\uc218\ub97c \uc644\uc131\ud558\uac70\ub098 \ubaa8\uc758\uc2dc\ud5d8\uc5d0 \ucc98\uc74c \ud569\uaca9\ud55c \ub0a0\uacfc \ud30c\uc77c\uc744 \ub9cc\ub4e0 \ub0a0\uc758 \ub0a0\uc9dc \ubc88\ud638, \uce90\ub9ad\ud130 \ud45c\uc2dc \uc2e4\ud5d8 \ubc30\uc815\uac12(\ucf1c\uc9d0/\uaebc\uc9d0)\ubfd0\uc774\uc5d0\uc694. \uc2e4\uc81c \ub0a0\uc9dc\uc640 \uc2dc\uac01, \ub2f5\uc548, \ud55c\uc790\ubcc4 \uae30\ub85d, \uc774\ub984\uacfc \uc5f0\ub77d\ucc98, \uae30\uae30 \uc2dd\ubcc4\uac12\uc740 \ub2f4\uae30\uc9c0 \uc54a\uc544\uc694.",'\ud30c\uc77c\uc740 \uc124\uc815 \ud654\uba74\uc758 "\ud559\uc2b5 \uae30\ub85d \u2192 \uc5f0\uad6c \ucc38\uc5ec"\uc5d0\uc11c \uc9c1\uc811 \uacf5\uc720 \ucc3d\uc744 \uc5f4\uc5b4 \ubcf4\ub0bc \ub54c\ub9cc \uae30\uae30 \ubc16\uc73c\ub85c \ub098\uac00\uc694. \uc571\uc774 \uc800\uc808\ub85c \ubcf4\ub0b4\ub294 \uc77c\uc740 \uc5c6\uc5b4\uc694.','\ucc38\uc5ec \ucf54\ub4dc\ub294 \uae30\uae30 \uc548\uc5d0\ub9cc \uc800\uc7a5\ub418\uace0 \ud559\uc2b5 \uae30\ub85d \ubc31\uc5c5 \ud30c\uc77c\uc5d0\ub294 \ub4e4\uc5b4\uac00\uc9c0 \uc54a\uc544\uc694. "\uc5f0\uad6c \ucc38\uc5ec"\uc5d0\uc11c \uc9c0\uc6b0\uac70\ub098 \ud559\uc2b5 \uae30\ub85d\uc744 \ucd08\uae30\ud654\ud558\uba74 \ud568\uaed8 \uc9c0\uc6cc\uc838\uc694. \ubaa8\uc9d1\ud560 \ub54c \ubc1b\uc740 \uc5f0\ub77d\ucc98\ub294 \uc9d1\uacc4 \ud30c\uc77c\uacfc \ub530\ub85c \ubcf4\uad00\ud574\uc694. \ucc38\uc5ec \ucf54\ub4dc\uc640 \uc5f0\ub77d\ucc98\ub97c \uc787\ub294 \uba85\ub2e8\uc740 \uc6b4\uc601\uc790\ub9cc \ubd10\uc694. \uce90\ub9ad\ud130 \ud45c\uc2dc \uc2e4\ud5d8 \ubc30\uc815\uac12(\ucf1c\uc9d0/\uaebc\uc9d0)\uc740 \ucc38\uc5ec \ucf54\ub4dc\ub97c \uc9c0\uc6b0\uac70\ub098 \ud559\uc2b5 \uae30\ub85d\uc744 \ucd08\uae30\ud654\ud574\ub3c4 \uae30\uae30\uc5d0 \ub0a8\uc544\uc11c, \uac19\uc740 \ucf54\ub4dc\ub97c \ub2e4\uc2dc \ub123\uc73c\uba74 \uc6d0\ub798 \ubc30\uc815\uc73c\ub85c \ub3cc\uc544\uac00\uc694.',"\ubcf4\uad00 \uae30\uac04: \uc9d1\uacc4 \ud30c\uc77c\uc740 \uc5f0\uad6c\uac00 \ub05d\ub09c \ub4a4 1\ub144 \uc548\uc5d0 \uc9c0\uc6cc\uc694. \uc5f0\ub77d\ucc98\uc640 \ucc38\uc5ec \ucf54\ub4dc \uba85\ub2e8\uc740 \uc5f0\uad6c\uac00 \ub05d\ub098\uba74 \ubc14\ub85c \uc9c0\uc6cc\uc694. \ucc38\uc5ec\ub97c \uadf8\ub9cc\ub450\uac70\ub098 \ubcf4\ub0b8 \ud30c\uc77c\uc744 \uc9c0\uc6cc \ub2ec\ub77c\uace0 \ud558\ub824\uba74 \ucc38\uc5ec \ucf54\ub4dc\uc640 \ud568\uaed8 \uc544\ub798 \ubb38\uc758\ucc98\ub85c \uc54c\ub824 \uc8fc\uc138\uc694."],t.s)
B.aE5=new A.l8("9. \uc5f0\uad6c \ucc38\uc5ec(\uc120\ud0dd)",B.ajp)
B.abo=s(["\uac1c\uc778\uc815\ubcf4\uc640 \uad00\ub828\ud574 \ubb3b\uace0 \uc2f6\uc740 \uac83\uc774 \uc788\uc73c\uba74 \uc544\ub798\ub85c \uc54c\ub824 \uc8fc\uc138\uc694.","\xb7 \uc6b4\uc601: \uc36c\uc6cd\uc2a4","\xb7 \ud68c\uc0ac \ud648\ud398\uc774\uc9c0: https://www.sunworks.kr","\xb7 \uacf5\uc2dd \uc571 \uc18c\uac1c: https://hanja-app.sunw.kr/","\xb7 \uc774\uba54\uc77c: support@sunworks.kr",'\uc571 \uc548\uc758 "\ubb38\ud56d \uc2e0\uace0" \uae30\ub2a5\uc73c\ub85c\ub3c4 \uc54c\ub824 \uc904 \uc218 \uc788\uc5b4\uc694. \uc774\ub54c \ub9cc\ub4e4\uc5b4\uc9c0\ub294 \uae00\uc5d0\ub294 \uc5b4\ub5a4 \ubb38\uc81c\uc600\ub294\uc9c0, \uace0\ub978 \uc0ac\uc720, \uc571 \ubc84\uc804, \uc2e0\uace0\ud55c \uc2dc\uac01\ub9cc \ub4e4\uc5b4\uac00\uc694. \uadf8 \uae00\ub3c4 \uc5ec\ub7ec\ubd84\uc774 \uacf5\uc720 \ucc3d\uc5d0\uc11c \ubcf4\ub0bc \ub54c\ub9cc \ub098\uac00\uc694.'],t.s)
B.aE2=new A.l8("10. \uad81\uae08\ud55c \uc810\uc774 \uc788\uc73c\uba74",B.abo)
B.atj=s(["\xb7 1.0 (2026\ub144 9\uc6d4 8\uc77c \uc2dc\ud589) \u2014 \ucc98\uc74c \ub9cc\ub4e4\uc5c8\uc5b4\uc694.","\xb7 1.1 (2026\ub144 9\uc6d4 26\uc77c \uc2dc\ud589) \u2014 \uc5f0\uad6c \ucc38\uc5ec(\uc120\ud0dd) \uc808\uc744 \ub354\ud588\uc5b4\uc694.","\xb7 1.2 (2026\ub144 10\uc6d4 2\uc77c \uc2dc\ud589) \u2014 \uc6b4\uc601 \ud68c\uc0ac\uc640 \uacf5\uc2dd \uc0ac\uc774\ud2b8, \ubb38\uc758 \uc774\uba54\uc77c\uc744 \uc548\ub0b4\ud588\uc5b4\uc694.","\ubc29\uce68\uc744 \uace0\uce60 \ub54c\ub294 \uc571 \uc548\uc758 \uc774 \ud654\uba74\uacfc \uc6f9 \ud398\uc774\uc9c0\ub97c \ud568\uaed8 \uace0\uce58\uace0, \ubc14\ub010 \ub0a0\uc9dc\ub97c \uc5ec\uae30\uc5d0 \uc801\uc744\uac8c\uc694."],t.s)
